def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_m, last_o = history[-1]
    rounds_left = 100 - n

    opp_c = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1

    start = n - 10
    if start < 0:
        start = 0
    rec10_c = 0
    for i in range(start, n):
        if history[i][1] == 'C':
            rec10_c += 1

    cc = cd = dd = dc = 0
    for i in range(1, n):
        prev_m = history[i - 1][0]
        cur_o = history[i][1]
        if prev_m == 'D':
            if cur_o == 'D':
                dd += 1
            else:
                cd += 1
        else:
            if cur_o == 'D':
                dc += 1
            else:
                cc += 1

    my_d_prev = cd + dd
    my_c_prev = cc + dc

    opp_d_streak = 0
    my_c_in_streak = 0
    start_streak = n
    i = n - 1
    while i >= 0:
        _, o = history[i]
        if o == 'D':
            opp_d_streak += 1
            if history[i][0] == 'C':
                my_c_in_streak += 1
            start_streak = i
            i -= 1
        else:
            break

    caused = False
    if opp_d_streak > 0:
        j = start_streak
        while j < n:
            if j > 0 and history[j - 1][0] == 'D':
                caused = True
                break
            j += 1

    hostile = False
    if opp_c * 2 < n:
        hostile = True
    elif n >= 5 and rec10_c <= 1:
        hostile = True
    elif opp_d_streak >= 6:
        hostile = True
    elif my_c_in_streak >= 3:
        hostile = True

    if hostile:
        return 'D'

    if last_m == 'D' and my_d_prev == 0 and rounds_left > 1:
        return 'C'

    if my_d_prev == 0:
        if opp_c == n and rounds_left <= 12:
            pd = 1.0
        elif n >= 30 and opp_c * 5 >= n * 4 and rounds_left <= 20:
            pd = 0.75
        else:
            pd = 0.0
    else:
        pd = (cd + 1.0) / (my_d_prev + 2.0)

    if my_c_prev == 0:
        pc = (opp_c + 1.0) / (n + 2.0)
    else:
        pc = (cc + 1.0) / (my_c_prev + 2.0)

    delta = pc - pd

    if last_o == 'D':
        if my_c_in_streak >= 2:
            return 'D'
        if caused and delta > 0.55 and pd < 0.65:
            return 'C'
        if last_m == 'D' and delta > 0.65 and pd < 0.65:
            return 'C'
        if last_m == 'C' and delta > 0.85 and opp_c * 4 >= n * 3 and rng.random() < 0.25:
            return 'C'
        return 'D'

    if pd >= 0.65:
        return 'D'

    if delta > 0.75:
        return 'C'

    if rounds_left <= 4:
        return 'D'

    if rounds_left > 35 and delta > 0.40:
        return 'C'

    if rounds_left > 15 and delta > 0.55:
        return 'C'

    if pc <= 0.35:
        return 'D'

    if opp_c * 4 >= n * 3 and pc > 0.60 and n < 75:
        return 'C'

    if pd >= 0.40 and opp_c * 2 >= n:
        return 'D'

    if opp_c * 2 >= n:
        return 'C'

    return 'D'
